package tech.lightclient.mixins.client;
import tech.lightclient.LightClient;import tech.lightclient.client.events.impl.client.EventAimAssist;import tech.lightclient.client.events.impl.client.EventKey;import tech.lightclient.client.events.impl.client.EventMouse;import tech.lightclient.client.events.impl.client.EventScroll;import tech.lightclient.client.utils.baritone.BaritoneRotationHook;

import tech.lightclient.client.utils.render.drag.DraggingManager;

import tech.lightclient.modules.impl.combat.AimBot;import tech.lightclient.client.utils.render.drag.api.Dragging;import tech.lightclient.modules.impl.render.CameraTweaks;import tech.lightclient.modules.impl.render.FreeLook;import tech.lightclient.ui.hud.HudSettingsOverlay;import tech.lightclient.ui.hud.MediaPlayer;import net.minecraft.client.Mouse;import net.minecraft.client.gui.screen.ChatScreen;import net.minecraft.client.input.MouseInput;import net.minecraft.client.util.InputUtil;import net.minecraft.util.math.MathHelper;import org.lwjgl.glfw.GLFW;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.Shadow;import org.spongepowered.asm.mixin.Unique;import org.spongepowered.asm.mixin.injection.At;import org.spongepowered.asm.mixin.injection.Inject;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;import static tech.lightclient.client.utils.client.IMinecraft.mc;@Mixin(Mouse.class)public class MouseMixin {    @Shadow    private double cursorDeltaX;    @Shadow    private double cursorDeltaY;    @Unique    private long light$lastAimAssistNs = 0L;    @Inject(method = "onMouseButton", at = @At("HEAD"))    public void onMouseButtonHook(long window, MouseInput input, int action, CallbackInfo ci) {        var client = mc;        if (client == null || window != client.getWindow().getHandle()) {            return;        }        int button = input.button();        if (client.currentScreen == null) {            LightClient.getEventBus().post(new EventMouse(button, action));            if (button != GLFW.GLFW_KEY_UNKNOWN) {                LightClient.getEventBus().post(new EventKey(EventKey.MOUSE_BUTTON_OFFSET + button, action, InputUtil.Type.MOUSE));            }        }        if (!(client.currentScreen instanceof ChatScreen) || LightClient.isHide() || button != 0) {            return;        }        double mouseX = client.mouse.getX();        double mouseY = client.mouse.getY();        if (HudSettingsOverlay.isOpen()) {            return;        }        if (action == 1) {            if (MediaPlayer.handleMouseClick(mouseX, mouseY, button)) {                return;            }            for (Dragging dragging : DraggingManager.draggables.values()) {                if (dragging.getModule() != null && dragging.getModule().isState() && dragging.onClick(mouseX, mouseY, button)) {                    break;                }            }        } else {            for (Dragging dragging : DraggingManager.draggables.values()) {                if (dragging.getModule() != null && dragging.getModule().isState()) {                    dragging.onRelease(button);                }            }        }    }    @Inject(method = "onMouseScroll", at = @At("HEAD"), cancellable = true)    public void onMouseScrollHook(long window, double horizontal, double vertical, CallbackInfo ci) {        var client = mc;        if (client == null || window != client.getWindow().getHandle()) {            return;        }        LightClient.getEventBus().post(new EventScroll(horizontal, vertical));        CameraTweaks cameraTweaks = LightClient.getFunctionManager().getCameraTweaks();        if (cameraTweaks != null && cameraTweaks.isZoomActive() && client.currentScreen == null) {            ci.cancel();        }    }    @Inject(method = "updateMouse", at = @At("HEAD"))    public void onUpdateMouse(double timeDelta, CallbackInfo ci) {        long now = System.nanoTime();        double deltaSeconds;        if (this.light$lastAimAssistNs == 0L) {            deltaSeconds = 1.0 / 120.0;        } else {            deltaSeconds = MathHelper.clamp((now - this.light$lastAimAssistNs) / 1_000_000_000.0, 0.001, 0.2);        }        this.light$lastAimAssistNs = now;                EventAimAssist aimAssistEvent = new EventAimAssist(this.cursorDeltaX, this.cursorDeltaY, deltaSeconds);

        AimBot aimBot = AimBot.getInstance();

        if (aimBot != null) {

            aimBot.resetAimAssistFrameFlag();

        }

        LightClient.getEventBus().post(aimAssistEvent);

        if (aimBot != null && aimBot.isState()) {

            aimBot.onAimAssist(aimAssistEvent);

        }

        this.cursorDeltaX = aimAssistEvent.getDeltaX();

        this.cursorDeltaY = aimAssistEvent.getDeltaY();        FreeLook freeLook = LightClient.getFunctionManager().getFreeLook();        if (freeLook != null && freeLook.isActive()) {            freeLook.addRotation((float) this.cursorDeltaX, (float) this.cursorDeltaY);            this.cursorDeltaX = 0.0;            this.cursorDeltaY = 0.0;            return;        }        if (BaritoneRotationHook.shouldCaptureMouse() && mc.currentScreen == null) {            BaritoneRotationHook.addCameraRotation((float) this.cursorDeltaX, (float) this.cursorDeltaY);            this.cursorDeltaX = 0.0;            this.cursorDeltaY = 0.0;        }    }}